/// Paths of the bundled brand images (generated by
/// `flutter test tool/app_icon/generate_brand_images_test.dart`).
///
/// Each has 1x, 2.0x and 3.0x variants; `Image.asset` picks the right one.
/// Prefer `TicketEmblem` when the mark must animate or change colour — these are
/// for places that need a plain image (sharing, notifications, empty states).
abstract final class AppImages {
  static const _brand = 'assets/images/brand';
  static const _placeholders = 'assets/images/placeholders';

  /// The ticket tilted like the app icon, with a soft shadow. Transparent, 160×128.
  static const logo = '$_brand/logo.png';

  /// The ticket upright, no shadow. Transparent, 128×80.
  static const logoFlat = '$_brand/logo_flat.png';

  /// White ticket with see-through details, for tinting (`color:`). Transparent, 128×80.
  static const logoMono = '$_brand/logo_mono.png';

  /// Ticket plus "Movie Tickets" in Poppins Bold, white text. Transparent, 360×64.
  static const wordmark = '$_brand/wordmark.png';

  /// The app icon as a rounded square (About screen, sharing). 192×192.
  static const appIcon = '$_brand/app_icon.png';

  /// Missing movie poster, 2:3 like `PosterCard`. 200×300.
  static const posterPlaceholder = '$_placeholders/poster.png';

  /// Missing movie banner, 16:9. 400×225.
  static const bannerPlaceholder = '$_placeholders/banner.png';

  static const all = [logo, logoFlat, logoMono, wordmark, appIcon, posterPlaceholder, bannerPlaceholder];
}
